import sys

# Increase recursion limit to handle deep expressions
sys.setrecursionlimit(20000)

class ExprError(Exception):
    """Exception raised by the evaluator."""
    def __init__(self, kind: str, pos: int):
        self.kind = kind
        self.pos = pos
        super().__init__(f'{kind} at position {pos}')


# ----------------------------------------------------------------------
# Tokenization
# ----------------------------------------------------------------------
def tokenize(src: str):
    tokens = []
    i = 0
    n = len(src)
    while i < n:
        ch = src[i]
        if ch.isspace():
            i += 1
            continue

        # integer literal
        if ch.isdigit():
            start = i
            j = i
            while j < n and src[j].isdigit():
                j += 1
            lit = src[start:j]
            if lit[0] == '0' and len(lit) > 1:
                raise ExprError('syntax', start)
            value = int(lit)
            tokens.append(('INT', value, start))
            i = j
            continue

        # identifier or keyword
        if ch.isalpha() or ch == '_':
            start = i
            j = i
            while j < n and (src[j].isalnum() or src[j] == '_'):
                j += 1
            name = src[start:j]
            if name == 'true':
                tokens.append(('TRUE', None, start))
            elif name == 'false':
                tokens.append(('FALSE', None, start))
            else:
                tokens.append(('IDENT', name, start))
            i = j
            continue

        # two-character operators
        if i + 1 < n:
            two = src[i:i+2]
            if two in ('**', '||', '&&', '==', '!=', '<=', '>='):
                tokens.append(('OP', two, i))
                i += 2
                continue

        # single-character operators and punctuation
        if ch in '+-*/%!?':
            tokens.append(('OP', ch, i))
            i += 1
            continue
        if ch == '(':
            tokens.append(('LPAREN', None, i))
            i += 1
            continue
        if ch == ')':
            tokens.append(('RPAREN', None, i))
            i += 1
            continue
        if ch == ',':
            tokens.append(('COMMA', None, i))
            i += 1
            continue
        if ch == '?':
            tokens.append(('QUESTION', None, i))
            i += 1
            continue
        if ch == ':':
            tokens.append(('COLON', None, i))
            i += 1
            continue

        # any other character is a syntax error
        raise ExprError('syntax', i)

    tokens.append(('EOF', None, len(src)))
    return tokens


# ----------------------------------------------------------------------
# AST node classes
# ----------------------------------------------------------------------
class Node:
    pass

class IntNode(Node):
    __slots__ = ('value', 'pos')
    def __init__(self, value, pos):
        self.value = value
        self.pos = pos

class BoolNode(Node):
    __slots__ = ('value', 'pos')
    def __init__(self, value, pos):
        self.value = value
        self.pos = pos

class VarNode(Node):
    __slots__ = ('name', 'pos')
    def __init__(self, name, pos):
        self.name = name
        self.pos = pos

class UnaryNode(Node):
    __slots__ = ('op', 'operand', 'pos')
    def __init__(self, op, operand, pos):
        self.op = op
        self.operand = operand
        self.pos = pos

class BinaryNode(Node):
    __slots__ = ('op', 'left', 'right', 'pos')
    def __init__(self, op, left, right, pos):
        self.op = op
        self.left = left
        self.right = right
        self.pos = pos

class TernaryNode(Node):
    __slots__ = ('cond', 'true_branch', 'false_branch', 'pos')
    def __init__(self, cond, true_branch, false_branch, pos):
        self.cond = cond
        self.true_branch = true_branch
        self.false_branch = false_branch
        self.pos = pos

class FuncCallNode(Node):
    __slots__ = ('name', 'args', 'pos')
    def __init__(self, name, args, pos):
        self.name = name
        self.args = args
        self.pos = pos


# ----------------------------------------------------------------------
# Parser
# ----------------------------------------------------------------------
class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.idx = 0
        self.n = len(tokens)

    def current(self):
        return self.tokens[self.idx]

    def current_type(self):
        return self.current()[0]

    def current_value(self):
        return self.current()[1]

    def current_pos(self):
        return self.current()[2]

    def consume(self):
        if self.idx < self.n - 1:
            self.idx += 1

    def expect(self, ttype, value=None):
        tok = self.current()
        if tok[0] != ttype or (value is not None and tok[1] != value):
            raise ExprError('syntax', tok[2])
        self.consume()

    def parse(self):
        node = self.parse_ternary()
        return node

    # 1. ternary
    def parse_ternary(self):
        cond = self.parse_or()
        if self.current_type() == 'QUESTION':
            op_pos = self.current_pos()
            self.consume()
            true_branch = self.parse_ternary()
            if self.current_type() != 'COLON':
                raise ExprError('syntax', self.current_pos())
            self.consume()
            false_branch = self.parse_ternary()
            return TernaryNode(cond, true_branch, false_branch, op_pos)
        return cond

    # 2. ||
    def parse_or(self):
        left = self.parse_and()
        while self.current_type() == 'OP' and self.current_value() == '||':
            op_pos = self.current_pos()
            self.consume()
            right = self.parse_and()
            left = BinaryNode('||', left, right, op_pos)
        return left

    # 3. &&
    def parse_and(self):
        left = self.parse_equality()
        while self.current_type() == 'OP' and self.current_value() == '&&':
            op_pos = self.current_pos()
            self.consume()
            right = self.parse_equality()
            left = BinaryNode('&&', left, right, op_pos)
        return left

    # 4. == !=  (non-associative)
    def parse_equality(self):
        left = self.parse_comparison()
        if self.current_type() == 'OP' and self.current_value() in ('==', '!='):
            op_pos = self.current_pos()
            op = self.current_value()
            self.consume()
            right = self.parse_comparison()
            if self.current_type() == 'OP' and self.current_value() in ('==', '!='):
                raise ExprError('syntax', self.current_pos())
            return BinaryNode(op, left, right, op_pos)
        return left

    # 5. < <= > >= (non-associative)
    def parse_comparison(self):
        left = self.parse_addition()
        if self.current_type() == 'OP' and self.current_value() in ('<', '<=', '>', '>='):
            op_pos = self.current_pos()
            op = self.current_value()
            self.consume()
            right = self.parse_addition()
            if self.current_type() == 'OP' and self.current_value() in ('<', '<=', '>', '>='):
                raise ExprError('syntax', self.current_pos())
            return BinaryNode(op, left, right, op_pos)
        return left

    # 6. + -
    def parse_addition(self):
        left = self.parse_multiplication()
        while self.current_type() == 'OP' and self.current_value() in ('+', '-'):
            op_pos = self.current_pos()
            op = self.current_value()
            self.consume()
            right = self.parse_multiplication()
            left = BinaryNode(op, left, right, op_pos)
        return left

    # 7. * / %
    def parse_multiplication(self):
        left = self.parse_exponent()
        while self.current_type() == 'OP' and self.current_value() in ('*', '/', '%'):
            op_pos = self.current_pos()
            op = self.current_value()
            self.consume()
            right = self.parse_exponent()
            left = BinaryNode(op, left, right, op_pos)
        return left

    # 8. unary
    def parse_unary(self):
        tok = self.current()
        if tok[0] == 'OP' and tok[1] in ('-', '!'):
            op_pos = tok[2]
            op = tok[1]
            self.consume()
            operand = self.parse_unary()
            return UnaryNode(op, operand, op_pos)
        return self.parse_exponent()

    # 9. exponent (right-associative)
    def parse_exponent(self):
        left = self.parse_primary()
        if self.current_type() == 'OP' and self.current_value() == '**':
            op_pos = self.current_pos()
            self.consume()
            right = self.parse_exponent_rhs()
            return BinaryNode('**', left, right, op_pos)
        return left

    def parse_exponent_rhs(self):
        left = self.parse_unary()
        if self.current_type() == 'OP' and self.current_value() == '**':
            op_pos = self.current_pos()
            self.consume()
            right = self.parse_exponent_rhs()
            return BinaryNode('**', left, right, op_pos)
        return left

    # 10. primary
    def parse_primary(self):
        tok_type = self.current_type()
        tok_pos = self.current_pos()
        if tok_type == 'INT':
            node = IntNode(self.current_value(), tok_pos)
            self.consume()
            return node
        if tok_type == 'TRUE':
            node = BoolNode(True, tok_pos)
            self.consume()
            return node
        if tok_type == 'FALSE':
            node = BoolNode(False, tok_pos)
            self.consume()
            return node
        if tok_type == 'IDENT':
            name = self.current_value()
            pos = tok_pos
            self.consume()
            if self.current_type() == 'LPAREN':
                # function call
                self.consume()  # consume '('
                args = []
                if self.current_type() == 'RPAREN':
                    # no arguments
                    self.consume()
                else:
                    args.append(self.parse_ternary())
                    while self.current_type() == 'COMMA':
                        self.consume()
                        args.append(self.parse_ternary())
                    if self.current_type() != 'RPAREN':
                        raise ExprError('syntax', self.current_pos())
                    self.consume()
                return FuncCallNode(name, args, pos)
            else:
                return VarNode(name, pos)
        if tok_type == 'LPAREN':
            self.consume()
            expr = self.parse_ternary()
            if self.current_type() != 'RPAREN':
                raise ExprError('syntax', self.current_pos())
            self.consume()
            return expr
        # any other token is syntax error
        raise ExprError('syntax', tok_pos)


# ----------------------------------------------------------------------
# Evaluator
# ----------------------------------------------------------------------
def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)

def is_bool(v):
    return isinstance(v, bool)

def eval_node(node, env):
    if isinstance(node, IntNode):
        return node.value
    if isinstance(node, BoolNode):
        return node.value
    if isinstance(node, VarNode):
        if node.name not in env:
            raise ExprError('name', node.pos)
        return env[node.name]
    if isinstance(node, UnaryNode):
        val = eval_node(node.operand, env)
        if node.op == '-':
            if not is_int(val):
                raise ExprError('type', node.pos)
            return -val
        if node.op == '!':
            if not is_bool(val):
                raise ExprError('type', node.pos)
            return not val
        # should not reach here
        raise Exception('Unknown unary op')
    if isinstance(node, BinaryNode):
        op = node.op
        if op in ('&&', '||'):
            left_val = eval_node(node.left, env)
            if not is_bool(left_val):
                raise ExprError('type', node.pos)
            if op == '&&':
                if not left_val:
                    return False
                right_val = eval_node(node.right, env)
                if not is_bool(right_val):
                    raise ExprError('type', node.pos)
                return left_val and right_val
            else:  # '||'
                if left_val:
                    return True
                right_val = eval_node(node.right, env)
                if not is_bool(right_val):
                    raise ExprError('type', node.pos)
                return left_val or right_val
        # arithmetic and others
        left_val = eval_node(node.left, env)
        right_val = eval_node(node.right, env)

        if op in ('+', '-', '*', '/', '%', '**'):
            if not is_int(left_val) or not is_int(right_val):
                raise ExprError('type', node.pos)
            if op == '+':
                return left_val + right_val
            if op == '-':
                return left_val - right_val
            if op == '*':
                return left_val * right_val
            if op == '/':
                if right_val == 0:
                    raise ExprError('zero-division', node.pos)
                q = abs(left_val) // abs(right_val)
                if (left_val ^ right_val) < 0:
                    q = -q
                return q
            if op == '%':
                if right_val == 0:
                    raise ExprError('zero-division', node.pos)
                q = abs(left_val) // abs(right_val)
                if (left_val ^ right_val) < 0:
                    q = -q
                return left_val - q * right_val
            if op == '**':
                if right_val < 0 or right_val > 1000:
                    raise ExprError('domain', node.pos)
                return pow(left_val, right_val)
        if op in ('<', '<=', '>', '>='):
            if not is_int(left_val) or not is_int(right_val):
                raise ExprError('type', node.pos)
            if op == '<':
                return left_val < right_val
            if op == '<=':
                return left_val <= right_val
            if op == '>':
                return left_val > right_val
            if op == '>=':
                return left_val >= right_val
        if op in ('==', '!='):
            if is_int(left_val) and is_int(right_val):
                eq = left_val == right_val
            elif is_bool(left_val) and is_bool(right_val):
                eq = left_val == right_val
            else:
                raise ExprError('type', node.pos)
            if op == '==':
                return eq
            else:
                return not eq
        # unknown operator
        raise Exception('Unknown binary op')
    if isinstance(node, TernaryNode):
        cond_val = eval_node(node.cond, env)
        if not is_bool(cond_val):
            raise ExprError('type', node.pos)
        if cond_val:
            return eval_node(node.true_branch, env)
        else:
            return eval_node(node.false_branch, env)
    if isinstance(node, FuncCallNode):
        name = node.name
        pos = node.pos
        if name not in ('min', 'max', 'abs'):
            raise ExprError('name', pos)
        # arity
        if name == 'abs':
            if len(node.args) != 1:
                raise ExprError('arity', pos)
        else:
            if len(node.args) < 1:
                raise ExprError('arity', pos)
        # evaluate arguments left-to-right
        arg_vals = []
        for arg in node.args:
            val = eval_node(arg, env)
            arg_vals.append(val)
        # type check
        if name == 'abs':
            if not is_int(arg_vals[0]):
                raise ExprError('type', pos)
            return abs(arg_vals[0])
        else:
            for v in arg_vals:
                if not is_int(v):
                    raise ExprError('type', pos)
            return min(arg_vals) if name == 'min' else max(arg_vals)
    raise Exception('Unknown node type')


# ----------------------------------------------------------------------
# Public API
# ----------------------------------------------------------------------
def evaluate(src: str, env: dict):
    """
    Evaluate the expression `src` under the variable environment `env`.
    Returns an int or bool.
    Raises ExprError on syntax, name, type, arity, zero-division, or domain errors.
    """
    tokens = tokenize(src)
    parser = Parser(tokens)
    node = parser.parse()
    # after parsing, we must be at EOF
    if parser.current_type() != 'EOF':
        raise ExprError('syntax', parser.current_pos())
    return eval_node(node, env)
